INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginne ich hier ohne Planung?', 2, '[{"text": "Nein", "correct": true, "because": "Planen ist erster Schritt"}, {"text": "Ja", "correct": false, "because": "Strukturierter Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt mache ich zuerst in diesem Prozess?', 3, '[{"text": "Planen", "correct": true, "because": "Ziele und Anforderungen festlegen"}, {"text": "Entwickeln", "correct": false, "because": "Folgt Planung"}, {"text": "Überwachen", "correct": false, "because": "Später im Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zu diesem Zyklus?', 5, '[{"text": "Testen", "correct": true, "because": "Qualität sichern"}, {"text": "Bereitstellen", "correct": true, "because": "Software ausliefern"}, {"text": "Einmalige Entwicklung", "correct": false, "because": "Kontinuierlich nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback wird integriert. b) Überwachen ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überwachen essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich in diesem Ablauf?', 4, '[{"text": "Entwickeln", "correct": false, "because": "Kern der Software"}, {"text": "Feedback integrieren", "correct": false, "because": "Verbesserung zentral"}, {"text": "Einmalige Lieferung", "correct": true, "because": "Kontinuierlicher Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal teste?', 2, '[{"text": "Nein", "correct": true, "because": "Testen fortlaufend"}, {"text": "Ja", "correct": false, "because": "Kontinuierlicher Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase wähle ich, um die Software auszuliefern?', 3, '[{"text": "Bereitstellen", "correct": true, "because": "Deployment-Schritt"}, {"text": "Überwachen", "correct": false, "because": "Nach Bereitstellung"}, {"text": "Planen", "correct": false, "because": "Vor Entwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sichern Zuverlässigkeit?', 5, '[{"text": "Testen", "correct": true, "because": "Fehler früh erkennen"}, {"text": "Überwachen", "correct": true, "because": "Laufzeit prüfen"}, {"text": "Einmalige Planung", "correct": false, "because": "Kontinuierlich nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Planen startet den Zyklus. b) Feedback ist unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Feedback essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Bereitstellen", "correct": false, "because": "Software ausliefern"}, {"text": "Überwachen", "correct": false, "because": "Leistung prüfen"}, {"text": "Statische Prozesse", "correct": true, "because": "Kontinuierlich anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Entwickle ich hier nur einmal?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierlicher Zyklus"}, {"text": "Ja", "correct": false, "because": "Iterative Entwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente verbessern die Software?', 4, '[{"text": "Feedback integrieren", "correct": true, "because": "Nutzerinput nutzen"}, {"text": "Testen", "correct": true, "because": "Qualität sichern"}, {"text": "Einmalige Bereitstellung", "correct": false, "because": "Kontinuierlich nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier nicht überwache. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Überwachen ist zentral"}, {"text": "Ja", "correct": false, "because": "Leistung im Blick"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich nach der Entwicklung?', 3, '[{"text": "Testen", "correct": true, "because": "Qualität prüfen"}, {"text": "Planen", "correct": false, "because": "Vor Entwicklung"}, {"text": "Überwachen", "correct": false, "because": "Nach Bereitstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bereitstellen liefert Software. b) Testen ist einmalig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Testen fortlaufend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat dieser Ablauf?', 5, '[{"text": "Schnelle Lieferung", "correct": true, "because": "Bereitstellen im Zyklus"}, {"text": "Zuverlässigkeit", "correct": true, "because": "Testen und Überwachen"}, {"text": "Einmalige Rückmeldung", "correct": false, "because": "Feedback kontinuierlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Entwickeln", "correct": false, "because": "Kern der Software"}, {"text": "Feedback integrieren", "correct": false, "because": "Verbesserung zentral"}, {"text": "Feste Zyklen", "correct": true, "because": "Kontinuierlich anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Überwachen hier unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Leistung im Blick"}, {"text": "Ja", "correct": false, "because": "Überwachen essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier einmal bereitstelle?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierliche Bereitstellung"}, {"text": "Ja", "correct": false, "because": "Zyklus wiederholt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach der Bereitstellung?', 4, '[{"text": "Überwachen", "correct": true, "because": "Leistung prüfen"}, {"text": "Entwickeln", "correct": false, "because": "Vor Bereitstellung"}, {"text": "Planen", "correct": false, "because": "Start des Zyklus"}]');
